//! Relic registry and effects (MOBILE 3.17.0).
//!
//! The 119 items come from `Economy.txt` (`items`), embedded as data in
//! `crate::data::RELICS` (generated by `tools/gen_data.py`). Only
//! structural/numeric fields are embedded (id, rarity, price, tier,
//! family, group, min round, max, starter/consumable/retired flags) — the
//! original Korean name/desc text is NOT copied. Display names below are
//! fresh Vietnamese wording written for this clone.
//!
//! # Implemented effects (P0)
//!
//! The eight starter relics (REA-REPORT §13.4 / §15.3):
//!
//! | id | Fresh Vietnamese name | Effect |
//! |----|----------------------|--------|
//! | `nail` | Đinh Cong | FillDeck: Success +4 |
//! | `file` | Đá Mài Cũ | FillDeck: Hold −2 / Success +2 |
//! | `seal` | Nút Thắt Đen | Chances: break chance ×0.85 |
//! | `coin` | Con Dấu Kiểm Định | +130 gold (flat) per Success/Great |
//! | `pin` | Đinh Vàng | FillDeck: Great +2 |
//! | `hold` | Đá Niêm Phong | FillDeck: Hold +2; every 2 consecutive Holds +1 grade |
//! | `shard` | Chén Thánh Tang Lễ | on break: scrap tribute = 30% of peak value (40% in Fever) |
//! | `repair` | Sắt Nối Nứt | break chance × max(0.4, 1 − 0.15·damageCount), damageCount caps at 4 |
//!
//! # Dead relics — never grant effects
//!
//! `patchbag`, `burial`, `ledger`, `safe` are Deferred in the original
//! (REA-REPORT §15.2): `Rank()` always returns 0 for them. §15.3 proved
//! patchbag and burial CONTRADICTED — they have live descriptions but no
//! working effect (a remake copying their descs would ship effects the
//! real game does not have). They are [`EffectStatus::Dead`] here.
//!
//! Every other relic is DATA ONLY for now: its registry entry exists, but
//! [`EffectStatus::NotImplemented`] is returned explicitly — never silently
//! wrong. See [`Loadout::unimplemented_owned`] for the owned-but-
//! unimplemented list (the game shell should warn the player).

use crate::data::RELICS;
use crate::tickets::{chances_weights, fill_deck, CampaignFields, DeckWeights, Outcome};
use std::fmt;

/// Relic family (from `Economy.txt` `family`).
///
/// The eight mastery families have Korean keys in the data; they are
/// mapped to English variants here (see `tools/gen_data.py`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RelicFamily {
    Success,
    Hold,
    Damage,
    Defense,
    Consumable,
    Achievement,
    Frenzy,
    Great,
    Mixed,
    Merchant,
    Break,
    Economy,
    Value,
    Utility,
    /// Citadel sword line mastery.
    Citadel,
    /// Holy sword line mastery.
    Holy,
    /// Sawblade line mastery.
    Saw,
    /// Dragonfang line mastery.
    Dragonfang,
    /// Runeblade line mastery.
    Rune,
    /// Splitblade line mastery.
    Split,
    /// World Tree line mastery.
    WorldTree,
    /// Fishblade line mastery.
    Fish,
}

/// One relic's registry entry (balance data only — no display text).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RelicDef {
    /// Registry key, e.g. `"nail"`.
    pub id: &'static str,
    /// Rarity: 0 = common, 1 = rare, 2 = legendary.
    pub rarity: u8,
    /// Shop price in swords/gold units (see `Economy.txt` `price`).
    pub price: u64,
    /// Tier 0–2 (shop wave gating).
    pub tier: u8,
    pub family: RelicFamily,
    /// `"relic"`, `"masterwork"`, `"consumable"` or `"merchant"`.
    pub group: &'static str,
    /// Earliest round this relic can appear (JSON `min`: 2 = round 2,
    /// 8 = mid wave, 16 = late wave).
    pub min_round: u32,
    /// Reproduced as-is from JSON `max`; its meaning is unconfirmed.
    pub max: u32,
    /// Offered as a starting relic.
    pub starter: bool,
    /// Single-use item.
    pub consumable: bool,
    /// Retired from the shop rotation (still in the registry).
    pub retired: bool,
}

impl RelicDef {
    /// Fresh Vietnamese display name written for this clone, if one has
    /// been written yet. `None` means "show the id for now" — names for
    /// the remaining relics are a content task, not a data task.
    pub fn display_name(&self) -> Option<&'static str> {
        match self.id {
            "nail" => Some("Đinh Cong"),
            "file" => Some("Đá Mài Cũ"),
            "seal" => Some("Nút Thắt Đen"),
            "coin" => Some("Con Dấu Kiểm Định"),
            "pin" => Some("Đinh Vàng"),
            "hold" => Some("Đá Niêm Phong"),
            "shard" => Some("Chén Thánh Tang Lễ"),
            "repair" => Some("Sắt Nối Nứt"),
            _ => None,
        }
    }
}

/// All 119 item definitions, in the order of `Economy.txt`.
pub fn all() -> &'static [RelicDef; 119] {
    &RELICS
}

/// Look a relic up by id. `None` for unknown ids.
pub fn by_id(id: &str) -> Option<&'static RelicDef> {
    RELICS.iter().find(|r| r.id == id)
}

/// Number of items with the given rarity (0, 1 or 2).
pub fn count_by_rarity(rarity: u8) -> usize {
    RELICS.iter().filter(|r| r.rarity == rarity).count()
}

/// The starter relics offered at run start (the 8-item pool, REA-REPORT
/// §13.4).
pub fn starters() -> impl Iterator<Item = &'static RelicDef> {
    RELICS.iter().filter(|r| r.starter)
}

/// The starter pool ids, in Economy.txt order.
pub const STARTER_POOL: [&str; 8] = [
    "nail", "file", "seal", "coin", "pin", "hold", "shard", "repair",
];

/// Relics that can NEVER satisfy a Rank() check (REA-REPORT §15.2):
/// `Rank()` returns 0 for these four ids regardless of ownership.
pub const DEFERRED_IDS: [&str; 4] = ["ledger", "safe", "patchbag", "burial"];

/// Whether a relic's effect is implemented in this slice.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EffectStatus {
    /// Fully implemented (one of the eight starters).
    Implemented,
    /// Dead in the original: live description, no working effect.
    /// Never grants effects, even if owned.
    Dead,
    /// Data exists, effect is NOT implemented yet. The string says why.
    NotImplemented(&'static str),
}

/// Effect status of a relic id.
pub fn effect_status(id: &str) -> Result<EffectStatus, RelicError> {
    match by_id(id) {
        None => Err(RelicError::UnknownRelic(id.to_string())),
        Some(_) => Ok(match id {
            "nail" | "file" | "seal" | "coin" | "pin" | "hold" | "shard" | "repair" => {
                EffectStatus::Implemented
            }
            "ledger" | "safe" | "patchbag" | "burial" => EffectStatus::Dead,
            _ => EffectStatus::NotImplemented("effect not implemented yet"),
        }),
    }
}

/// Errors from relic operations.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RelicError {
    /// No relic with this id exists in the registry.
    UnknownRelic(String),
    /// The relic is already owned (owned relics never reappear).
    Duplicate(String),
    /// The relic exists but its effect is not implemented yet.
    NotImplemented(String),
}

impl fmt::Display for RelicError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RelicError::UnknownRelic(id) => write!(f, "unknown relic id: {id}"),
            RelicError::Duplicate(id) => write!(f, "relic already owned: {id}"),
            RelicError::NotImplemented(id) => {
                write!(f, "relic effect not implemented yet: {id}")
            }
        }
    }
}

impl std::error::Error for RelicError {}

/// Gold paid by the Coin relic per Success/Great outcome (§15.3).
pub const COIN_GOLD_PER_SUCCESS: f64 = 130.0;

/// Extra grade granted every N consecutive Holds by the Hold relic.
pub const HOLD_STREAK_FOR_GRADE: u32 = 2;

/// Shard scrap rate on break: 30% of peak value, 40% in Fever (§15.3).
pub const SHARD_SCRAP_RATE: f64 = 0.30;
pub const SHARD_SCRAP_RATE_FEVER: f64 = 0.40;

/// Side effects a strike produces through owned relics.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct StrikeEffects {
    /// Gold added to the sword's value by this strike (Coin relic).
    pub gold: f64,
    /// Extra forge grades from this strike (Hold relic streak).
    pub extra_grade: u32,
}

/// Tracks consecutive Hold outcomes for the Hold relic.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct HoldTracker {
    consecutive: u32,
}

impl HoldTracker {
    pub fn new() -> Self {
        Self::default()
    }

    /// Consecutive Holds so far.
    pub fn consecutive(&self) -> u32 {
        self.consecutive
    }

    /// Record one strike outcome. Returns the extra grade granted by the
    /// Hold relic: 1 on every 2nd consecutive Hold, else 0. Any other
    /// outcome resets the streak.
    pub fn record(&mut self, outcome: Outcome) -> u32 {
        if outcome == Outcome::Hold {
            self.consecutive += 1;
            if self.consecutive % HOLD_STREAK_FOR_GRADE == 0 {
                1
            } else {
                0
            }
        } else {
            self.consecutive = 0;
            0
        }
    }
}

/// The relics a player owns in a run, plus their per-run state.
///
/// `Loadout` only ever *applies* the eight implemented starter effects.
/// Owning other relics is allowed (their data is real) but they change
/// nothing yet — see [`Loadout::unimplemented_owned`]. Dead relics
/// (patchbag/burial/ledger/safe) never grant effects even when owned.
#[derive(Debug, Default)]
pub struct Loadout {
    relics: Vec<&'static RelicDef>,
    hold_tracker: HoldTracker,
}

impl Loadout {
    pub fn new() -> Self {
        Self::default()
    }

    /// A loadout owning exactly the eight starter relics (the P0 run
    /// start). Whether the original grants all eight or lets the player
    /// pick is unresolved statically — P0 grants the whole pool, matching
    /// the PC clone's approach. TODO-RE: confirm starter granting.
    pub fn starters() -> Self {
        let mut loadout = Self::new();
        for id in STARTER_POOL {
            loadout
                .add(id)
                .expect("starter pool ids must exist in the registry");
        }
        loadout
    }

    /// Owned relics, in acquisition order.
    pub fn relics(&self) -> &[&'static RelicDef] {
        &self.relics
    }

    /// True if the relic is owned.
    pub fn contains(&self, id: &str) -> bool {
        self.relics.iter().any(|r| r.id == id)
    }

    /// Rank(id) (REA-REPORT §15.2): 1 if owned and NOT Deferred, else 0.
    /// Deferred ids (ledger/safe/patchbag/burial) always return 0.
    pub fn rank(&self, id: &str) -> u32 {
        if DEFERRED_IDS.contains(&id) {
            return 0;
        }
        if self.contains(id) {
            1
        } else {
            0
        }
    }

    /// Add a relic to the loadout.
    ///
    /// Fails for unknown ids and for duplicates (owned relics never
    /// reappear). Adding an *unimplemented* relic succeeds — it is data
    /// only; see [`Loadout::unimplemented_owned`]. Adding a *dead* relic
    /// also succeeds (it is in the registry) but it never grants effects.
    pub fn add(&mut self, id: &str) -> Result<(), RelicError> {
        let def = by_id(id).ok_or_else(|| RelicError::UnknownRelic(id.to_string()))?;
        if self.contains(id) {
            return Err(RelicError::Duplicate(id.to_string()));
        }
        self.relics.push(def);
        Ok(())
    }

    /// Owned relics whose effects are NOT implemented yet.
    pub fn unimplemented_owned(&self) -> Vec<&'static str> {
        self.relics
            .iter()
            .filter(|r| matches!(effect_status(r.id), Ok(EffectStatus::NotImplemented(_))))
            .map(|r| r.id)
            .collect()
    }

    /// Owned relics that are dead in the original (never grant effects).
    pub fn dead_owned(&self) -> Vec<&'static str> {
        self.relics
            .iter()
            .filter(|r| matches!(effect_status(r.id), Ok(EffectStatus::Dead)))
            .map(|r| r.id)
            .collect()
    }

    /// Build the final draw deck for a strike at `grade`.
    ///
    /// FillDeck (§15.1) → Chances weights (§12.8): the deck is built
    /// from the owned relics' Rank values, then the Danger rescale and
    /// the risk factors (seal ×0.85, tongs ×0.75 at grade > 5, repair
    /// per-damage) are applied. `damage_count` is the current sword's
    /// consecutive Damage count (0 when repair is not owned).
    pub fn build_deck(
        &self,
        grade: u32,
        campaign: &CampaignFields,
        fever: bool,
        damage_count: u32,
    ) -> DeckWeights {
        let deck = fill_deck(&|id| self.rank(id), campaign, fever);
        let weights = chances_weights(
            grade,
            deck,
            1.0,
            &|id| self.rank(id),
            damage_count,
            fever,
        );
        DeckWeights::new(weights)
    }

    /// Side effects of one strike outcome through owned relics.
    ///
    /// - Coin: +130 gold on Success or Great (via the sword's flat).
    /// - Hold relic: every 2nd consecutive Hold grants +1 grade
    ///   (tracked internally; any other outcome resets the streak).
    pub fn strike_effects(&mut self, outcome: Outcome) -> StrikeEffects {
        let gold = if self.contains("coin") {
            match outcome {
                Outcome::Success | Outcome::Great => COIN_GOLD_PER_SUCCESS,
                _ => 0.0,
            }
        } else {
            0.0
        };
        // The tracker always records (keeps streak state in sync); the
        // grade is only granted while the Hold relic is owned.
        let streak_grade = self.hold_tracker.record(outcome);
        let extra_grade = if self.contains("hold") {
            streak_grade
        } else {
            0
        };
        StrikeEffects { gold, extra_grade }
    }

    /// Scrap tribute from a broken sword (shard relic, §15.3): 30% of
    /// the sword's peak value, 40% while Fever is active. 0 when shard
    /// is not owned.
    pub fn break_scrap(&self, peak_value: f64, fever: bool) -> f64 {
        if !self.contains("shard") {
            return 0.0;
        }
        let rate = if fever {
            SHARD_SCRAP_RATE_FEVER
        } else {
            SHARD_SCRAP_RATE
        };
        peak_value * rate
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_has_119_items() {
        assert_eq!(all().len(), 119);
        assert_eq!(count_by_rarity(0), 33);
        assert_eq!(count_by_rarity(1), 61);
        assert_eq!(count_by_rarity(2), 25);
    }

    #[test]
    fn registry_lookup_and_families() {
        let nail = by_id("nail").unwrap();
        assert_eq!(nail.family, RelicFamily::Success);
        assert_eq!((nail.rarity, nail.price, nail.tier), (0, 1, 0));
        assert!(nail.starter);
        assert_eq!(by_id("cornerstone").unwrap().family, RelicFamily::Citadel);
        assert_eq!(by_id("deeppearl").unwrap().family, RelicFamily::Fish);
        assert_eq!(by_id("nope"), None);
    }

    #[test]
    fn eight_starters_are_implemented() {
        for id in STARTER_POOL {
            assert_eq!(effect_status(id), Ok(EffectStatus::Implemented), "{id}");
        }
        assert_eq!(
            starters().map(|r| r.id).collect::<Vec<_>>(),
            STARTER_POOL.to_vec()
        );
    }

    #[test]
    fn dead_relics_never_grant_effects() {
        for id in ["patchbag", "burial", "ledger", "safe"] {
            assert_eq!(effect_status(id), Ok(EffectStatus::Dead), "{id}");
        }
        // Rank() is always 0 for Deferred ids, even when owned.
        let mut loadout = Loadout::new();
        loadout.add("patchbag").unwrap();
        loadout.add("burial").unwrap();
        assert_eq!(loadout.rank("patchbag"), 0);
        assert_eq!(loadout.rank("burial"), 0);
        assert_eq!(loadout.dead_owned(), vec!["patchbag", "burial"]);
    }

    #[test]
    fn starter_display_names_are_fresh_vietnamese() {
        assert_eq!(by_id("nail").unwrap().display_name(), Some("Đinh Cong"));
        assert_eq!(
            by_id("coin").unwrap().display_name(),
            Some("Con Dấu Kiểm Định")
        );
        assert_eq!(by_id("shard").unwrap().display_name(), Some("Chén Thánh Tang Lễ"));
        assert_eq!(by_id("repair").unwrap().display_name(), Some("Sắt Nối Nứt"));
        assert_eq!(by_id("knot").unwrap().display_name(), None);
    }

    #[test]
    fn loadout_rejects_unknown_and_duplicates() {
        let mut loadout = Loadout::new();
        assert_eq!(
            loadout.add("nope"),
            Err(RelicError::UnknownRelic("nope".to_string()))
        );
        loadout.add("nail").unwrap();
        assert_eq!(
            loadout.add("nail"),
            Err(RelicError::Duplicate("nail".to_string()))
        );
    }

    #[test]
    fn rank_is_one_when_owned() {
        let mut loadout = Loadout::new();
        loadout.add("nail").unwrap();
        assert_eq!(loadout.rank("nail"), 1);
        assert_eq!(loadout.rank("pin"), 0);
    }

    #[test]
    fn nail_adds_four_success_via_deck() {
        let mut loadout = Loadout::new();
        loadout.add("nail").unwrap();
        let deck = loadout.build_deck(0, &CampaignFields::default(), false, 0);
        // Grade 0: break chance is 0, so the 9 BREAK tickets are removed
        // by the Danger rescale; Success share = 16/25.
        let pm = deck.per_mille();
        assert_eq!(pm[3], 640, "nail Success per-mille {pm:?}");
    }

    #[test]
    fn coin_pays_130_gold_on_success_and_great_only() {
        let mut loadout = Loadout::new();
        loadout.add("coin").unwrap();
        assert_eq!(loadout.strike_effects(Outcome::Success).gold, 130.0);
        assert_eq!(loadout.strike_effects(Outcome::Great).gold, 130.0);
        assert_eq!(loadout.strike_effects(Outcome::Hold).gold, 0.0);
        assert_eq!(loadout.strike_effects(Outcome::Break).gold, 0.0);
        assert_eq!(loadout.strike_effects(Outcome::Damage).gold, 0.0);
    }

    #[test]
    fn hold_streak_grants_grade_every_second_consecutive_hold() {
        let mut loadout = Loadout::new();
        loadout.add("hold").unwrap();
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 0);
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 1);
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 0);
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 1);
        // A non-hold outcome resets the streak.
        assert_eq!(loadout.strike_effects(Outcome::Success).extra_grade, 0);
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 0);
        assert_eq!(loadout.strike_effects(Outcome::Hold).extra_grade, 1);
    }

    #[test]
    fn shard_scrap_is_30_percent_or_40_in_fever() {
        let mut loadout = Loadout::new();
        loadout.add("shard").unwrap();
        assert_eq!(loadout.break_scrap(1000.0, false), 300.0);
        assert_eq!(loadout.break_scrap(1000.0, true), 400.0);
        let plain = Loadout::new();
        assert_eq!(plain.break_scrap(1000.0, false), 0.0);
    }

    #[test]
    fn repair_reduces_break_by_damage_count() {
        let mut loadout = Loadout::new();
        loadout.add("repair").unwrap();
        // Grade 30, no damage: break share = 0.71.
        let w0 = loadout.build_deck(30, &CampaignFields::default(), false, 0);
        let p0 = w0.probability(Outcome::Break);
        // After 2 Damage outcomes: × (1 − 0.30) = ×0.70.
        let w2 = loadout.build_deck(30, &CampaignFields::default(), false, 2);
        let p2 = w2.probability(Outcome::Break);
        assert!((p0 - 0.71).abs() < 1e-9, "p0 {p0}");
        assert!((p2 - 0.71 * 0.70).abs() < 1e-9, "p2 {p2}");
        // After 4+ Damage: floor at ×0.40.
        let w4 = loadout.build_deck(30, &CampaignFields::default(), false, 4);
        let p4 = w4.probability(Outcome::Break);
        assert!((p4 - 0.71 * 0.40).abs() < 1e-9, "p4 {p4}");
    }

    #[test]
    fn unimplemented_owned_is_listed_explicitly() {
        let mut loadout = Loadout::new();
        loadout.add("nail").unwrap();
        loadout.add("knot").unwrap();
        loadout.add("shard").unwrap();
        assert!(loadout.unimplemented_owned().contains(&"knot"));
        assert!(!loadout.unimplemented_owned().contains(&"nail"));
        assert!(!loadout.unimplemented_owned().contains(&"shard"));
    }
}
